WITH metrics AS (SELECT *, LAG(age) OVER w_hist prev_age, LAG(credit_limit) OVER w_hist prev_credit_limit, LEAD(credit_limit) OVER w_hist next_credit_limit, ROW_NUMBER() OVER w_hist row_seq, AVG(age) OVER (PARTITION BY country ORDER BY age, id ROWS BETWEEN 5 PRECEDING AND 1 PRECEDING) age_avg_5_prior FROM customers WINDOW w_hist AS (PARTITION BY country ORDER BY credit_limit, id)) SELECT id, name, email, country, city, segment, is_active, prev_age, prev_credit_limit FROM metrics ORDER BY segment DESC;
